package com.yuegang.zhihui.search.api;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.search.application.SearchDeletionService;import com.yuegang.zhihui.search.security.SearchInternalSecurity;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.Map;import org.springframework.web.bind.annotation.*;@RestController public final class SearchDeletionController{private final SearchDeletionService service;private final SearchInternalSecurity security;public SearchDeletionController(SearchDeletionService s,SearchInternalSecurity x){service=s;security=x;}@PostMapping("/internal/v1/search/delete-document")ApiResponse<Map<String,Boolean>>delete(@Valid @RequestBody DeleteDocumentCommand c,HttpServletRequest r){security.verify(r);service.deleteDocument(c.documentId());return ApiResponse.success(Map.of("completed",true),TraceIdResolver.resolve(r));}}
